insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-00000000000a', 'en', null, 'Networking Fundamentals', 'A hands-on first course in how computer networks move data — from the OSI model to IP subnetting, devices, protocols, and security. Structure follows the publicly published CompTIA Network+ objective domains and targets Network+-style foundations; all teaching prose is original.', null, 'work', 10, true, 'technology', '{bbbb0002-0000-4000-8000-000000000001}')
